[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\LogitechGHubUpdaterDemandStart.ps1"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$TaskName='Lacksan-EXP-055-LabHarness';$ServiceName='LGHUBUpdaterService';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Test-Elevation{$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(-not$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function Ensure-Directory($p){if(-not(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function Write-Json($p,$v){$v|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $p -Encoding UTF8}
function Read-Json($p){if(-not(Test-Path -LiteralPath $p)){throw "Required state missing: $p"};Get-Content -LiteralPath $p -Raw|ConvertFrom-Json}
function Median($v){$a=@($v|Where-Object{$null-ne$_}|ForEach-Object{[double]$_}|Sort-Object);if(!$a.Count){return $null};$m=[int][math]::Floor($a.Count/2);if($a.Count%2){return$a[$m]};($a[$m-1]+$a[$m])/2}
function Mad($v){$a=@($v|Where-Object{$null-ne$_}|ForEach-Object{[double]$_});if(!$a.Count){return $null};$m=Median $a;Median @($a|ForEach-Object{[math]::Abs($_-$m)})}
function Paths($d){[pscustomobject]@{State=Join-Path $d 'harness-state.json';ProviderState=Join-Path $d 'provider-state.json';ProviderLog=Join-Path $d 'provider-events.jsonl';Summary=Join-Path $d 'summary.json'}}
function Resolve-Run{if($RunDirectory){return(Resolve-Path $RunDirectory).Path};$a=Read-Json $ActivePointer;(Resolve-Path ([string]$a.runDirectory)).Path}
function Provider($a,$d){$p=Paths $d;& $ProviderPath -Action $a -StatePath $p.ProviderState -LogPath $p.ProviderLog}
function BootUtc{((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function ProtectedSnapshot{$services=@();foreach($n in 'Tailscale','TermService','WinDefend','mpssvc','wuauserv'){try{$s=Get-Service $n -ErrorAction Stop;$services+=[pscustomobject]@{name=$n;status="$($s.Status)";startType="$($s.StartType)"}}catch{$services+=[pscustomobject]@{name=$n;status='absent';startType=$null}}};[pscustomobject]@{services=$services;processes=@(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName-match'(?i)tailscale|msrdc|windowsapp|omnissa|horizon|vmware-view|wswc'}|Select-Object ProcessName,Id,Responding)}}
function SampleSystem{[pscustomobject]@{cpu=[double](Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;disk=[double](Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec}}
function ServiceSnap{$s=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction Stop;$p=$null;if([int]$s.ProcessId-gt0){$g=Get-Process -Id ([int]$s.ProcessId) -ErrorAction SilentlyContinue;$w=Get-CimInstance Win32_Process -Filter "ProcessId=$($s.ProcessId)" -ErrorAction SilentlyContinue;if($g-and$w){$p=[pscustomobject]@{pid=$s.ProcessId;cpuMs=$g.TotalProcessorTime.TotalMilliseconds;readBytes=$w.ReadTransferCount;writeBytes=$w.WriteTransferCount}}};[pscustomobject]@{startMode=$s.StartMode;state=$s.State;process=$p}}
function Collect($phase,$ordinal,$d){$boot=BootUtc;$before=ServiceSnap;$pb=ProtectedSnapshot;$samples=@();$collector=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$samples+=SampleSystem;if($i-lt$count-1){Start-Sleep $SampleIntervalSeconds}};$after=ServiceSnap;$cpu=$null;$read=$null;$write=$null;if($before.process-and$after.process-and$before.process.pid-eq$after.process.pid){$cpu=$after.process.cpuMs-$before.process.cpuMs;$read=$after.process.readBytes-$before.process.readBytes;$write=$after.process.writeBytes-$before.process.writeBytes};[ordered]@{schema=1;experiment='EXP-055';phase=$phase;ordinal=$ordinal;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');system=@{cpuMedianPercent=Median @($samples.cpu);cpuMadPercent=Mad @($samples.cpu);diskMedianBytesPerSec=Median @($samples.disk);diskMadBytesPerSec=Mad @($samples.disk)};service=@{before=$before;after=$after;cpuDeltaMs=$cpu;readDeltaBytes=$read;writeDeltaBytes=$write;startedDuringSample=(!$before.process-and$after.process)};protected=@{before=$pb;after=ProtectedSnapshot};functional=@{gHubManualLaunch=$null;deviceDetection=$null;updateCheck=$null;hidReadiness=$null};instrumentation=@{collectorCpuDeltaMs=([double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds-$collector);sampleCount=$samples.Count}}}
function Summarize($d){$runs=@(Get-ChildItem $d -Filter 'run-*.json' -File|Sort-Object Name|ForEach-Object{Read-Json $_.FullName});if(!$runs.Count){throw 'No runs found'};$groups=[ordered]@{};foreach($phase in 'Baseline','Treatment'){$g=@($runs|Where-Object{$_.phase-eq$phase});$groups[$phase]=[ordered]@{runs=$g.Count;cpuMedianPercent=@{median=Median @($g.system.cpuMedianPercent);mad=Mad @($g.system.cpuMedianPercent)};diskMedianBytesPerSec=@{median=Median @($g.system.diskMedianBytesPerSec);mad=Mad @($g.system.diskMedianBytesPerSec)};serviceCpuDeltaMs=@{median=Median @($g.service.cpuDeltaMs);mad=Mad @($g.service.cpuDeltaMs)}}};$s=[ordered]@{schema=1;experiment='EXP-055';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');classification='inconclusive';groups=$groups;limitations=@('G Hub demand launch, device detection, update check, and HID readiness require physical functional validation')};Write-Json (Join-Path $d 'summary.json') $s;$s}
function Register-Task($d){$exe=(Get-Command powershell.exe).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$pr=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;if($PSCmdlet.ShouldProcess($TaskName,'Register continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Force|Out-Null}}
function Remove-Task{if(Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false}}
function Reboot{if($AllowAutomaticReboot){Restart-Computer -Force}else{Write-Output 'Reboot required; collection resumes at next logon.'}}
Test-Elevation;if(-not(Test-Path $ProviderPath)){throw 'Provider missing'}
switch($Action){
'Start'{Ensure-Directory $EvidenceRoot;if(Test-Path $ActivePointer){throw 'Active EXP-055 run exists'};$check=Provider 'Check' $EvidenceRoot;if(-not$check.Support.Supported){throw 'Provider support check failed'};$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss');$d=Join-Path $EvidenceRoot $stamp;Ensure-Directory $d;Provider 'Capture' $d|Out-Null;Write-Json (Paths $d).State @{schema=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null};Write-Json $ActivePointer @{runDirectory=$d};Register-Task $d;Reboot}
'Continue'{$d=Resolve-Run;$p=Paths $d;$s=Read-Json $p.State;$boot=(BootUtc).ToString('o');if($s.lastBootUtc-eq$boot){throw 'Duplicate collection from same boot refused'};if($s.phase-eq'Treatment'){Provider 'VerifyReboot' $d|Out-Null}else{$cur=Provider 'Check' $d;$orig=Read-Json $p.ProviderState;if($cur.Service.StartMode-ne$orig.service.StartMode-or[int]$cur.Service.DelayedAutoStart-ne[int]$orig.service.DelayedAutoStart){throw 'Baseline configuration drift detected'}};$n=[int]$s.completedRuns+1;$r=Collect $s.phase $n $d;Write-Json (Join-Path $d ("run-{0}-{1:D2}.json"-f$s.phase,$n)) $r;$s.completedRuns=$n;$s.lastBootUtc=$boot;if($n-ge[int]$s.runsPerArm){if($s.phase-eq'Baseline'){$s.phase='Treatment';$s.completedRuns=0;Provider 'Apply' $d|Out-Null}else{Provider 'Rollback' $d|Out-Null;Summarize $d|Out-Null;Remove-Task;Remove-Item $ActivePointer -Force;Write-Json $p.State $s;return Read-Json $p.Summary}};Write-Json $p.State $s;Reboot}
'Status'{if(Test-Path $ActivePointer){$d=Resolve-Run;Read-Json (Paths $d).State}else{[pscustomobject]@{active=$false}}}
'Summarize'{$d=Resolve-Run;Summarize $d}
'Stop'{$d=Resolve-Run;Provider 'Rollback' $d|Out-Null;Remove-Task;Remove-Item $ActivePointer -Force -ErrorAction SilentlyContinue;[pscustomobject]@{stopped=$true;runDirectory=$d}}
}